package com.hbm.machine.radar;
import com.hbm.multiblock.DummyableBlock;import com.mojang.serialization.MapCodec;import net.minecraft.core.BlockPos;import net.minecraft.world.InteractionResult;import net.minecraft.world.entity.player.Player;import net.minecraft.world.level.Level;import net.minecraft.world.level.block.SoundType;import net.minecraft.world.level.block.entity.*;import net.minecraft.world.level.block.state.BlockState;import net.minecraft.world.level.material.MapColor;import net.minecraft.world.phys.BlockHitResult;
public final class RadarScreenBlock extends DummyableBlock{public RadarScreenBlock(){super(Properties.of().mapColor(MapColor.METAL).strength(5,6).sound(SoundType.STONE).requiresCorrectToolForDrops().noOcclusion());}@Override protected MapCodec<? extends DummyableBlock> codec(){return simpleCodec(p->new RadarScreenBlock());}@Override public int[] dimensions(){return new int[]{1,0,0,0,1,0};}@Override public BlockEntity newBlockEntity(BlockPos p,BlockState s){return isCore(s)?new RadarScreenBlockEntity(p,s):null;}@Override public <T extends BlockEntity> BlockEntityTicker<T> getTicker(Level level,BlockState s,BlockEntityType<T> type){return isCore(s)?createTickerHelper(type,RadarContent.SCREEN_ENTITY.get(),RadarScreenBlockEntity::tick):null;}@Override protected InteractionResult useWithoutItem(BlockState s,Level level,BlockPos p,Player player,BlockHitResult hit){if(player.isShiftKeyDown())return InteractionResult.PASS;var core=findCore(level,p);if(core!=null&&level.getBlockEntity(core) instanceof RadarScreenBlockEntity screen&&screen.linked&&level.isClientSide&&level.getBlockEntity(new BlockPos(screen.refX,screen.refY,screen.refZ)) instanceof RadarBlockEntity)RadarBlockEntity.OPEN.accept(new BlockPos(screen.refX,screen.refY,screen.refZ));return level.isClientSide?InteractionResult.PASS:InteractionResult.CONSUME;}}
